//! RGS-UT 2026-09-19 JST — cluster-ops 域 IT (outbox_coverage 子桶)
//!
//! `integration_outbox_coverage`
//!
//! 场景: 验证 cluster-ops 域 outbox 基础设施对 v1.2 候选清单中 cluster_ops 域条目的
//!       命名合规性 + 实际可被 `InMemoryOutboxRepository` 接受。
//!
//! 设计目标 (per ULYS-103 acceptance #5: 6 域 cargo test outbox_coverage 全绿):
//! - 验证 cluster-ops 域 outbox 表 migration (`0002_outbox.sql` + `0003_outbox_check_idempotent.sql`)
//! - 验证 v1.2 候选清单中 cluster_ops 域 3 条 (`rgs.cluster_ops.node.joined.v1` /
//!   `rgs.cluster_ops.node.left.v1` / `rgs.cluster_ops.shard.rebalanced.v1`) 通过
//!   `SubjectBuilder::domain_event` + `parse()` 命名合规
//! - 验证 `InMemoryOutboxRepository` 接受 cluster_ops 域条目
//!
//! 注: cluster_ops 是**唯一**含下划线的 6 域白名单段 (per shared-platform::subject::parse()
//!     L73-82 match arm), 其他 5 域均为单词. 本测试 fail-closed 验证此特殊约定.

use std::sync::Arc;
use uuid::Uuid;

use shared_platform::outbox::{InMemoryOutboxRepository, OutboxEntry, OutboxRepository};
use shared_platform::subject::{parse, SubjectBuilder, SubjectDomain};

use sqlx::postgres::PgPoolOptions;

// ============================================================================
// cluster_ops 域 v1.2 候选清单 (per 09a §C.1 cluster_ops 域)
// ============================================================================

const CLUSTER_OPS_V1_2_SUBJECTS: &[&str] = &[
    "rgs.cluster_ops.node.joined.v1",
    "rgs.cluster_ops.node.left.v1",
    "rgs.cluster_ops.shard.rebalanced.v1",
];

/// 与生产代码命名约定对齐 (per shared-platform::subject::SubjectBuilder::domain_event)
#[test]
fn cluster_ops_v1_2_subjects_match_subject_builder() {
    let expected_pairs = [
        ("cluster_ops", "node.joined", 1u32),
        ("cluster_ops", "node.left", 1u32),
        ("cluster_ops", "shard.rebalanced", 1u32),
    ];

    assert_eq!(
        CLUSTER_OPS_V1_2_SUBJECTS.len(),
        expected_pairs.len(),
        "CLUSTER_OPS_V1_2_SUBJECTS (={}) vs 期望条目 (={}) 不一致",
        CLUSTER_OPS_V1_2_SUBJECTS.len(),
        expected_pairs.len(),
    );

    for (idx, (domain, event_type, version)) in expected_pairs.iter().enumerate() {
        let built = SubjectBuilder::domain_event(domain, event_type, *version);
        assert_eq!(
            built, CLUSTER_OPS_V1_2_SUBJECTS[idx],
            "SubjectBuilder::domain_event({:?}, {:?}, {:?}) 与 v1.2 候选条目 #{} 不一致",
            domain, event_type, version, idx,
        );
    }
}

/// cluster_ops 域 subject 命名合规: `parse()` 全部识别为 SubjectDomain::Domain 且第 2 段 = "cluster_ops"
#[test]
fn cluster_ops_v1_2_subjects_parse_compliant() {
    for subject in CLUSTER_OPS_V1_2_SUBJECTS {
        let (domain, _rest) = parse(subject).unwrap_or_else(|e| {
            panic!("cluster_ops 域 subject {} 解析失败: {}", subject, e);
        });

        assert_eq!(
            domain,
            SubjectDomain::Domain,
            "cluster_ops 域 subject {} 应被识别为 SubjectDomain::Domain",
            subject
        );

        let parts: Vec<&str> = subject.split('.').collect();
        assert_eq!(
            parts[1], "cluster_ops",
            "cluster_ops 域 subject {} 第 2 段应为 'cluster_ops', 实际为 {}",
            subject, parts[1],
        );

        // 第 2 段含下划线, 应被识别为 cluster_ops 域 (而非 cluster 或 ops 单独的域)
        assert!(
            parts[1].contains('_'),
            "cluster_ops 域 subject {} 第 2 段必须含下划线 (cluster_ops 唯一约定), 实际为 {}",
            subject, parts[1],
        );
    }
}

/// cluster-ops 域 outbox 基础设施 readiness
#[test]
fn cluster_ops_outbox_infrastructure_readiness() {
    assert!(
        CLUSTER_OPS_V1_2_SUBJECTS.len() >= 3,
        "cluster_ops 域 v1.2 候选清单至少 3 条, 当前 = {}",
        CLUSTER_OPS_V1_2_SUBJECTS.len(),
    );
}

/// cluster-ops 域 OutboxEntry append + list_pending 生命周期
#[tokio::test]
async fn cluster_ops_outbox_entry_lifecycle() {
    let pool = lazy_pool();
    let repo = InMemoryOutboxRepository::new();

    for subject in &CLUSTER_OPS_V1_2_SUBJECTS[..2] {
        let entry = OutboxEntry::new(
            subject.to_string(),
            format!(r#"{{"domain":"cluster_ops","subject":"{}"}}"#, subject),
            Uuid::new_v4(),
        );

        repo.append(&entry, &pool)
            .await
            .unwrap_or_else(|e| panic!("cluster_ops 域 {} append 失败: {}", subject, e));

        let pending = repo
            .list_pending(10)
            .await
            .unwrap_or_else(|e| panic!("cluster_ops 域 list_pending 失败: {}", e));
        assert!(
            pending.iter().any(|e| e.subject == *subject),
            "cluster_ops 域 {} 应出现在 list_pending 结果中",
            subject,
        );
    }
}

/// fail-closed: 域不匹配的 subject 不应被识别为 cluster_ops 域
#[test]
fn cluster_ops_other_domain_subjects_not_misclassified() {
    let non_cluster_ops_subjects = [
        "rgs.player.character.created.v1",
        "rgs.economy.wallet.committed.v1",
        "rgs.match.match.finished.v1",
        "rgs.social.friend.added.v1",
        "rgs.admin.ban.applied.v1",
    ];

    for subject in non_cluster_ops_subjects {
        let (_domain, _) = parse(subject).unwrap();

        let parts: Vec<&str> = subject.split('.').collect();
        assert_ne!(
            parts[1], "cluster_ops",
            "{} 的第 2 段不应为 'cluster_ops' (实际 = {})",
            subject, parts[1],
        );
    }
}

fn lazy_pool() -> sqlx::PgPool {
    PgPoolOptions::new()
        .max_connections(1)
        .connect_lazy("postgres://localhost/nonexistent")
        .expect("lazy connect should not fail")
}

#[allow(dead_code)]
fn _unused() -> Arc<InMemoryOutboxRepository> {
    Arc::new(InMemoryOutboxRepository::new())
}